import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {
 static final String H="dev/zomboid/firstaid/ZeroParts";
 static void verify(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 static byte[] patch(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);Set<String> changed=new HashSet<>();for(MethodNode m:c.methods){
 if(Set.of("isDead","calculateNewCurrentHealth","hasAllCriticalPartsCollapsed","hasCriticalPartCollapsed").contains(m.name)){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;if(m.name.startsWith("has")){if(m.name.equals("hasCriticalPartCollapsed")){m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/firstaid/Revival","active","(Ljava/lang/Object;)Z",false));}else m.instructions.add(new InsnNode(ICONST_0));m.instructions.add(new InsnNode(IRETURN));}else{m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,H,m.name.equals("isDead")?"dead":"health","(Ljava/lang/Object;Ljava/lang/Object;)"+(m.name.equals("isDead")?"Z":"F"),false));m.instructions.add(new InsnNode(m.name.equals("isDead")?IRETURN:FRETURN));}changed.add(m.name);}
 if(m.name.equals("handlePostDamage")){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new VarInsnNode(ALOAD,2));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/firstaid/Revival","post","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.add(new InsnNode(RETURN));changed.add(m.name);}
 if(m.name.equals("syncVanillaHealth")&&m.desc.equals("(Lnet/minecraft/world/entity/player/Player;)V")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new InsnNode(ACONST_NULL));h.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/firstaid/Revival","post","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insert(h);changed.add("syncVanillaHealth");}
 if(m.name.equals("tick")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,2));h.add(new MethodInsnNode(INVOKESTATIC,H,"tick","(Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insert(h);changed.add(m.name);}}
 if(changed.size()!=7)throw new IllegalStateException(changed.toString());ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);byte[] out=w.toByteArray();verify(out);System.out.println("Verified model methods: "+changed);return out;}
 public static void main(String[] a)throws Exception{Map<String,byte[]> add=new TreeMap<>();try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(v->v.toString().endsWith(".class")).toList()){byte[] b=Files.readAllBytes(p);verify(b);add.put(Path.of(a[2]).relativize(p).toString(),b);}}
 try(ZipFile in=new ZipFile(a[0]);ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var entries=in.entries();entries.hasMoreElements();){ZipEntry e=entries.nextElement();byte[] b=in.getInputStream(e).readAllBytes();if(e.getName().equals("ichttt/mods/firstaid/common/damagesystem/PlayerDamageModel.class"))b=patch(b);if(e.getName().equals("ichttt/mods/firstaid/client/StatusEffectLayer.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(m.name.equals("render"))for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,1));h.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/firstaid/RevivalHud","render","(Ljava/lang/Object;)V",false));m.instructions.insertBefore(n,h);}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();verify(b);}if(Set.of("ichttt/mods/firstaid/common/util/CommonUtils.class","ichttt/mods/firstaid/survival/ClinicalHooks.class","ichttt/mods/firstaid/compat/lrtactical/TreatmentV33.class").contains(e.getName())){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);
 if(c.name.endsWith("CommonUtils")){MethodNode m=new MethodNode(ACC_PUBLIC|ACC_STATIC,"killWhenBodyDepleted","(Lnet/minecraft/world/entity/player/Player;Lnet/minecraft/world/damagesource/DamageSource;)V",null,null);m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/firstaid/Revival","bodyFatal","(Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.add(new InsnNode(RETURN));c.methods.add(m);}
 else for(MethodNode m:c.methods)for(AbstractInsnNode n:m.instructions.toArray()){if(n instanceof MethodInsnNode x&&x.name.equals("killPlayerDirectly"))x.name="killWhenBodyDepleted";if(n instanceof LdcInsnNode x&&"killPlayerDirectly".equals(x.cst))x.cst="killWhenBodyDepleted";if(c.name.endsWith("ClinicalHooks")&&n instanceof FieldInsnNode x&&x.name.equals("currentHealth")&&n.getPrevious() instanceof FieldInsnNode f&&f.name.equals("HEAD")){m.instructions.remove(f);InsnList h=new InsnList();h.add(new InsnNode(ACONST_NULL));h.add(new MethodInsnNode(INVOKESTATIC,H,"health","(Ljava/lang/Object;Ljava/lang/Object;)F",false));m.instructions.insertBefore(n,h);m.instructions.remove(n);}}
 ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();verify(b);}
 out.putNextEntry(new ZipEntry(e.getName()));out.write(b);out.closeEntry();}for(var e:add.entrySet()){out.putNextEntry(new ZipEntry(e.getKey()));out.write(e.getValue());out.closeEntry();}}}
}
